lor:#dfd3b2}.rules-card p{font-size:9px;line-height:1.45;color:#9b9ba4;margin:4px 0 0}.rules-card b{color:#dbca99}.game-footer{display:flex;justify-content:space-between;align-items:center;padding:17px 0 0;color:#555863;font-size:7px;letter-spacing:1.2px}.game-footer button{background:none;border:0;color:#9a8b67;font-size:8px;letter-spacing:1px;cursor:pointer}.modal-backdrop{position:fixed;inset:0;z-index:20;background:#06070bd9;backdrop-filter:blur(8px);display:grid;place-items:center;padding:18px}.modal-backdrop[hidden],.game[hidden],.intro[hidden]{display:none}.modal{width:min(460px,100%);background:radial-gradient(ellipse at 50% 0,#272433,#151720 55%);border:1px solid #c9aa624b;box-shadow:0 22px 90px #000b;padding:35px;position:relative}.modal-close{position:absolute;right:15px;top:12px;border:0;background:none;color:#85848d;font-size:24px;cursor:pointer}.modal h2{font-size:28px;margin:0 0 8px}.modal-copy{font-size:11px;color:#9b9ca5;margin:0 0 23px}.setup-options{display:grid;grid-template-columns:1fr 1fr;gap:12px}.setup-options label{display:flex;flex-direction:column;gap:7px;color:#a8a7ae;font-size:8px;letter-spacing:1.4px}.setup-options select,.setup-options input{width:100%;padding:11px 10px;color:#e6e1d7;background:#0f1118;border:1px solid #ffffff1d;border-radius:2px;font:11px var(--sans);outline:none}.setup-options select:focus,.setup-options input:focus{border-color:#c4a95c}.setup-note{display:flex;gap:11px;margin:20px 0;padding:12px;background:#ffffff07;border:1px solid #ffffff0c}.setup-note span{color:var(--gold);font-size:16px}.setup-note p{font-size:10px;color:#a3a2aa;line-height:1.55;margin:0}.modal-start{width:100%;display:flex;justify-content:center;align-items:center}.event-modal{text-align:center;width:min(430px,100%);padding:38px}.event-symbol{width:55px;height:55px;border:1px solid #d2b86e66;color:#dec57d;display:grid;place-items:center;border-radius:50%;font-size:26px;margin:0 auto 19px;box-shadow:0 0 32px #c8a95112}.event-modal .eyebrow{just