(() => {
  const $ = (id) => document.getElementById(id);
  const canvas = $('board'), ctx = canvas.getContext('2d');
  const state = { players: [], turn: 0, round: 1, seconds: 3600, active: false, busy: false, voice: true, rolls: 0, lastDice: 1, eventAction: null, raf: 0 };
  const colors = ['#d3b86e','#8fc0b3','#c293c9','#df8b75'];
  const marks = ['✦','☾','♜','✧'];
  const path = [];
  for (let x=-4;x<=3;x++) path.push({x,y:-2});
  for (let y=-1;y<=2;y++) path.push({x:4,y});
  for (let x=3;x>=-4;x--) path.push({x,y:3});
  for (let y=2;y>=-1;y--) path.push({x:-4,y});
  const tileTypes = ['gate','sigil','omen','sigil','key','sigil','keeper','omen','sigil','key','sigil','omen','key','sigil','omen','keeper','sigil','key','omen','sigil','key','sigil','omen','sigil'];
  const tileNames = {gate:'THE GATE',sigil:'SIGIL',key:'KEY',omen:'OMEN',keeper:'KEEPER'};
  let W=0,H=0,dpr=1;
  const messages = [
    ['“Take a sigil. Leave a memory.”','THE KEEPER'],['“The gate remembers every face.”','THE KEEPER'],['“Run if you like. I have all night.”','THE KEEPER'],['“Did you hear that behind you?”','THE KEEPER'],['“Some doors open from the wrong side.”','THE KEEPER']
  ];
  const orders = [
    {title:'THE KEEPER DEMANDS A TITHE',copy:'“A little something for the passage. You know the toll.”',order:'Surrender 1 sigil. If you have none, lose your next turn.',do:p=>{if(p.sigils>0){p.sigils--;return `${p.name} surrendered a sigil to the Keeper.`}p.skip=true;return `${p.name} must sit out their next turn.`}},
    {title:'THE KEEPER CALLS YOUR NAME',copy:'“Look at me when I am speaking to you.”',order:'Go back 3 spaces. The night is not done with you.',do:p=>{p.pos=(p.pos-3+path.length)%path.length;return `${p.name} was sent back three spaces.`}},
    {title:'THE KEEPER WANTS A DANCE',copy:'“One step forward, two steps where I say.”',order:'Give up 1 key, or if you have none, lose 2 sigils.',do:p=>{if(p.keys>0){p.keys--;return `${p.name} paid the Keeper one key.`}p.sigils=Math.max(0,p.sigils-2);return `${p.name} lost two sigils to the Keeper.`}},
    {title:'THE KEEPER SAYS: BE STILL',copy:'“The quiet ones last the longest.”',order:'You may not roll next turn. Keep your eyes open.',do:p=>{p.skip=true;return `${p.name} has been ordered to miss a turn.`}},
    {title:'THE KEEPER OFFERS A BARGAIN',copy:'“One for you… one for me. We both leave happy.”',order:'Gain 1 sigil. The Keeper moves you 2 spaces toward the gate.',do:p=>{p.sigils++;p.pos=(p.pos+2)%path.length;return `${p.name} took the bargain: +1 sigil, moved 2 spaces.`}}
  ];
  const cards = [
    {title:'A CANDLE IN THE DARK',text:'A lost traveler presses a sigil into your palm.',do:p=>{p.sigils++;return `${p.name} found a sigil in the dark.`}},
    {title:'THE OLD IRON KEY',text:'A cold key lies beneath the cracked stone.',do:p=>{p.keys++;return `${p.name} found a key.`}},
    {title:'FOOTSTEPS BEHIND YOU',text:'You turn. No one there. You lose a moment—and a sigil.',do:p=>{p.sigils=Math.max(0,p.sigils-1);return `${p.name} lost a sigil to the shadows.`}},
    {title:'A SHORTCUT THROUGH THE FOG',text:'The path folds in on itself. Move ahead two spaces.',do:p=>{p.pos=(p.pos+2)%path.length;return `${p.name} found a shortcut and moved 2 spaces.`}},
    {title:'THE TOLLKEEPER',text:'A gloved hand appears. Pay one key or hand over a sigil.',do:p=>{if(p.keys>0)p.keys--;else p.sigils=Math.max(0,p.sigils-1);return `${p.name} paid the toll.`}},
    {title:'A MOMENT OF CLARITY',text:'For once, the whispers are quiet. Take another sigil.',do:p=>{p.sigils++;return `${p.name} found a second wind (+1 sigil).`}},
    {title:'THE WANDERING LANTERN',text:'It leads you onward, but refuses to show the way back.',do:p=>{p.pos=(p.pos+3)%path.length;return `${p.name} followed a lantern 3 spaces ahead.`}},
    {title:'A HAUNTED MIRROR',text:'Your reflection looks better equipped. Take one of its keys.',do:p=>{p.keys++;return `${p.name} claimed a key from the mirror.`}}
  ];

  function resize(){const r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;dpr=Math.min(window.devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);drawBoard()}
  function project(p){const scale=Math.min(W/575,H/345);return{x:W/2+(p.x-p.y)*35*scale,y:H/2+5+(p.x+p.y)*20*scale}}
  function polygon(points,fill,stroke,line=1){ctx.beginPath();points.forEach((p,i)=>{const a=project(p);i?ctx.lineTo(a.x,a.y):ctx.moveTo(a.x,a.y)});ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=line;ctx.stroke()}}
  function tilePoly(p,lift=0){const s=Math.min(W/575,H/345),dx=17*s,dy=11*s;return [{x:p.x,y:p.y,ox:-dx,oy:0},{x:p.x,y:p.y,ox:0,oy:-dy},{x:p.x,y:p.y,ox:dx,oy:0},{x:p.x,y:p.y,ox:0,oy:dy}].map(v=>{const q=project(v);return{x:q.x+v.ox,y:q.y+v.oy-lift}})}
  function drawBoard(){if(!W||!H)return;ctx.clearRect(0,0,W,H);const s=Math.min(W/575,H/345);ctx.save();
